import type { ReactNode } from "react";

type BrandIconProps = Readonly<{ className?: string }>;

function BrandSvg({
  className,
  viewBox,
  children,
}: BrandIconProps & Readonly<{ viewBox: string; children: ReactNode }>) {
  return (
    <svg
      aria-hidden="true"
      focusable="false"
      viewBox={viewBox}
      className={className}
      fill="currentColor"
    >
      {children}
    </svg>
  );
}

